<script setup lang="ts">import{reactive,ref}from'vue';import{adminApi}from'../api';import{ApiError,useAuthStore}from'@leadnews/shared';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';const f=reactive({name:'',password:''}),busy=ref(false),a=useAuthStore(),r=useRouter();async function go(){busy.value=true;try{const x=await adminApi.login(f.name,f.password);a.login(x.token,{id:x.userId,nickname:x.nickname},'ADMIN');r.push('/audit')}catch(e){ElMessage.error(e instanceof ApiError?e.message:'登录失败')}finally{busy.value=false}}</script><template><main class="login-wrap"><section class="login-card"><div class="eyebrow">CONTENT GOVERNANCE</div><h1>内容治理中心</h1><p class="meta">审核与频道配置均受后端权限保护</p><el-form class="stack" style="margin-top:24px" @submit.prevent="go"><el-input v-model="f.name" placeholder="管理员账号"/><el-input v-model="f.password" type="password" show-password placeholder="密码"/><el-button type="primary" native-type="submit" :loading="busy">安全登录</el-button></el-form></section></main></template>
